using System.Text; using System.Threading.RateLimiting; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using MaintenancePRO.Api.Security;
using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.RateLimiting; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
using Microsoft.OpenApi.Models;
var b=WebApplication.CreateBuilder(args);
b.Services.AddControllers(); b.Services.AddEndpointsApiExplorer();
b.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="MaintenancePRO API",Version="v1",Description="API maintenance sécurisée. Utiliser Authorize avec le jeton JWT."});
o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Description="Saisir uniquement le jeton reçu au login (sans préfixe Bearer).",Name="Authorization",In=ParameterLocation.Header,Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT"});
o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});
b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("Default")));
b.Services.AddIdentityCore<ApplicationUser>(o=>{o.Password.RequiredLength=12;o.Password.RequireDigit=true;o.Password.RequireLowercase=true;o.Password.RequireUppercase=true;o.Password.RequireNonAlphanumeric=true;o.User.RequireUniqueEmail=true;o.Lockout.AllowedForNewUsers=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);})
 .AddRoles<IdentityRole>().AddEntityFrameworkStores<AppDbContext>().AddSignInManager();
var jwtKey=b.Configuration["Jwt:Key"]; if(string.IsNullOrWhiteSpace(jwtKey)||Encoding.UTF8.GetByteCount(jwtKey)<32)throw new InvalidOperationException("Clé JWT absente ou trop courte. Configure Jwt:Key via User Secrets ou variable d'environnement (32 octets minimum).");
b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.MapInboundClaims=true;o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=b.Configuration["Jwt:Issuer"],ValidateAudience=true,ValidAudience=b.Configuration["Jwt:Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30)};});
b.Services.AddAuthorization(o=>{o.AddPolicy("AdminOnly",p=>p.RequireRole(AppRoles.Admin));o.AddPolicy("ManageEquipment",p=>p.RequireRole(AppRoles.Admin,AppRoles.Supervisor));o.AddPolicy("ManageMaintenance",p=>p.RequireRole(AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician));});
b.Services.AddScoped<TokenService>(); b.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.AddPolicy("auth",ctx=>RateLimitPartition.GetFixedWindowLimiter(ctx.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=8,Window=TimeSpan.FromMinutes(1),QueueLimit=0,AutoReplenishment=true}));});
var app=b.Build();
using(var scope=app.Services.CreateScope()){var sp=scope.ServiceProvider;var db=sp.GetRequiredService<AppDbContext>();await db.Database.EnsureCreatedAsync();var rm=sp.GetRequiredService<RoleManager<IdentityRole>>();foreach(var role in new[]{AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician,AppRoles.User})if(!await rm.RoleExistsAsync(role))await rm.CreateAsync(new IdentityRole(role));
var email=app.Configuration["BootstrapAdmin:Email"];var password=app.Configuration["BootstrapAdmin:Password"];if(!string.IsNullOrWhiteSpace(email)&&!string.IsNullOrWhiteSpace(password)){var um=sp.GetRequiredService<UserManager<ApplicationUser>>();if(await um.FindByEmailAsync(email)==null){var admin=new ApplicationUser{UserName=email,Email=email,EmailConfirmed=true,DisplayName="Administrateur",Status=AccountStatus.Active};var cr=await um.CreateAsync(admin,password);if(cr.Succeeded)await um.AddToRoleAsync(admin,AppRoles.Admin);else app.Logger.LogError("Création admin impossible: {Errors}",string.Join(",",cr.Errors.Select(x=>x.Code)));}}}
app.Use(async(ctx,next)=>{ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["X-Frame-Options"]="DENY";ctx.Response.Headers["Referrer-Policy"]="no-referrer";ctx.Response.Headers["Cache-Control"]="no-store";ctx.Response.Headers["Permissions-Policy"]="camera=(), microphone=(), geolocation=()";await next();});
if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}else{app.UseHttpsRedirection();}
app.UseRateLimiter();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();
